erDiagram
  CUSTOMER["Customer"] {
    uuid id PK
    varchar email UK "unique login"
    varchar name
  }
  ORDER {
    uuid id PK
    uuid customer_id FK
    decimal total
    varchar status
  }
  ORDER_ITEM {
    uuid order_id PK,FK
    uuid product_id PK,FK
    int quantity
  }
  PRODUCT {
    uuid id PK
    varchar sku UK
    decimal unit_price
  }
  CUSTOMER ||--o{ ORDER : places
  ORDER ||--|{ ORDER_ITEM : contains
  PRODUCT ||--o{ ORDER_ITEM : "referenced by"
